import{a as e,c as t,i as n,l as r,r as i,s as a,t as o}from"./app-B8uz0aqq.js";var s=JSON.parse(`{"path":"/qa/q1-server-architecture.html","title":"Q1: 请画出你熟悉的 MMORPG 服务器架构图，说明各组件的职责和通信方式","lang":"en-US","frontmatter":{},"filePathRelative":"qa/q1-server-architecture.md","git":{"createdTime":1773965296000,"updatedTime":1773965296000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),c={name:`q1-server-architecture.md`};function l(o,s,c,l,u,d){let f=r(`Mermaid`);return t(),n(`div`,null,[s[0]||=e(`<h1 id="q1-请画出你熟悉的-mmorpg-服务器架构图-说明各组件的职责和通信方式" tabindex="-1"><a class="header-anchor" href="#q1-请画出你熟悉的-mmorpg-服务器架构图-说明各组件的职责和通信方式"><span>Q1: 请画出你熟悉的 MMORPG 服务器架构图，说明各组件的职责和通信方式</span></a></h1><h2 id="问题分析" tabindex="-1"><a class="header-anchor" href="#问题分析"><span>问题分析</span></a></h2><p>本题考察对 MMORPG 服务器整体架构的理解，需要：</p><ol><li>画出完整的服务器架构图</li><li>说明各组件的职责</li><li>说明组件间的通信方式</li></ol><h2 id="参考架构-bigworld-kbengine-风格" tabindex="-1"><a class="header-anchor" href="#参考架构-bigworld-kbengine-风格"><span>参考架构：BigWorld/KBEngine 风格</span></a></h2><h3 id="整体架构图" tabindex="-1"><a class="header-anchor" href="#整体架构图"><span>整体架构图</span></a></h3>`,6),a(f,{code:``}),s[1]||=i(`h3`,{id:`登录流程图`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#登录流程图`},[i(`span`,null,`登录流程图`)])],-1),a(f,{code:``}),s[2]||=e(`<hr><h2 id="各组件职责详解" tabindex="-1"><a class="header-anchor" href="#各组件职责详解"><span>各组件职责详解</span></a></h2><h3 id="_1-客户端层" tabindex="-1"><a class="header-anchor" href="#_1-客户端层"><span>1. 客户端层</span></a></h3><table><thead><tr><th>组件</th><th>说明</th></tr></thead><tbody><tr><td>Unity客户端</td><td>PC端主流游戏引擎</td></tr><tr><td>Web客户端</td><td>H5小游戏、网页游戏</td></tr><tr><td>移动客户端</td><td>iOS/Android原生或Unity导出</td></tr></tbody></table><h3 id="_2-接入层" tabindex="-1"><a class="header-anchor" href="#_2-接入层"><span>2. 接入层</span></a></h3><h4 id="gatewayapp-网关服务器" tabindex="-1"><a class="header-anchor" href="#gatewayapp-网关服务器"><span>GatewayApp（网关服务器）</span></a></h4><p><strong>职责</strong>：</p><ul><li>客户端连接管理（维持长连接）</li><li>消息路由转发</li><li>会话管理（Session管理）</li><li>防攻击（限流、黑名单）</li><li>消息编解码</li></ul><p><strong>通信方式</strong>：</p><ul><li>与客户端：TCP/KCP/WebSocket + Protobuf</li><li>与内部服务：TCP + 自定义RPC协议</li></ul><h3 id="_3-登录服务" tabindex="-1"><a class="header-anchor" href="#_3-登录服务"><span>3. 登录服务</span></a></h3><h4 id="loginapp-登录服务器" tabindex="-1"><a class="header-anchor" href="#loginapp-登录服务器"><span>LoginApp（登录服务器）</span></a></h4><p><strong>职责</strong>：</p><ul><li>账号密码验证</li><li>服务器列表分发</li><li>与BaseAppMgr协调分配BaseApp</li><li>登录态管理</li></ul><p><strong>通信方式</strong>：</p><ul><li>与GatewayApp：RPC</li><li>与DBMgr：RPC</li><li>与BaseAppMgr：RPC</li></ul><h3 id="_4-管理服务层" tabindex="-1"><a class="header-anchor" href="#_4-管理服务层"><span>4. 管理服务层</span></a></h3><h4 id="baseappmgr-基础应用管理器" tabindex="-1"><a class="header-anchor" href="#baseappmgr-基础应用管理器"><span>BaseAppMgr（基础应用管理器）</span></a></h4><p><strong>职责</strong>：</p><ul><li>管理所有BaseApp实例</li><li>负责新玩家连接分配</li><li>BaseApp负载均衡</li><li>跟踪BaseApp状态</li></ul><h4 id="cellappmgr-空间应用管理器" tabindex="-1"><a class="header-anchor" href="#cellappmgr-空间应用管理器"><span>CellAppMgr（空间应用管理器）</span></a></h4><p><strong>职责</strong>：</p><ul><li>管理所有CellApp实例</li><li>空间分区负载均衡</li><li>动态调整Cell边界</li><li>Entity跨CellApp迁移调度</li></ul><h3 id="_5-基础服务层" tabindex="-1"><a class="header-anchor" href="#_5-基础服务层"><span>5. 基础服务层</span></a></h3><h4 id="baseapp-基础应用" tabindex="-1"><a class="header-anchor" href="#baseapp-基础应用"><span>BaseApp（基础应用）</span></a></h4><p><strong>职责</strong>：</p><ul><li>管理玩家的Proxy（Base Entity）</li><li>处理非空间相关逻辑： <ul><li>背包系统</li><li>好友系统</li><li>邮件系统</li><li>任务系统</li><li>商城交易</li></ul></li><li>作为客户端的通信锚点</li><li>消息重定向到CellApp</li></ul><p><strong>通信方式</strong>：</p><ul><li>与GatewayApp：长连接RPC</li><li>与CellApp：长连接RPC</li><li>与DBMgr：异步RPC</li></ul><h3 id="_6-空间服务层" tabindex="-1"><a class="header-anchor" href="#_6-空间服务层"><span>6. 空间服务层</span></a></h3><h4 id="cellapp-空间应用" tabindex="-1"><a class="header-anchor" href="#cellapp-空间应用"><span>CellApp（空间应用）</span></a></h4><p><strong>职责</strong>：</p><ul><li>管理空间区域（Cell）</li><li>处理空间相关逻辑： <ul><li>玩家移动</li><li>AOI系统</li><li>战斗系统</li><li>NPC AI</li><li>技能释放</li><li>场景对象管理</li></ul></li><li>Entity的位置管理</li></ul><p><strong>通信方式</strong>：</p><ul><li>与BaseApp：长连接RPC</li><li>与相邻CellApp：Entity同步</li><li>与DBMgr：异步RPC</li></ul><h3 id="_7-数据服务层" tabindex="-1"><a class="header-anchor" href="#_7-数据服务层"><span>7. 数据服务层</span></a></h3><h4 id="dbmgr-数据库管理器" tabindex="-1"><a class="header-anchor" href="#dbmgr-数据库管理器"><span>DBMgr（数据库管理器）</span></a></h4><p><strong>职责</strong>：</p><ul><li>数据库连接池管理</li><li>异步数据存取</li><li>玩家数据持久化</li><li>账号数据管理</li></ul><p><strong>数据库划分</strong>：</p><ul><li><strong>AccountDB</strong>：账号信息、登录记录</li><li><strong>CharacterDB</strong>：角色数据、属性、背包</li><li><strong>WorldDB</strong>：世界数据、公会、排行</li></ul><h4 id="redis-缓存集群" tabindex="-1"><a class="header-anchor" href="#redis-缓存集群"><span>Redis（缓存集群）</span></a></h4><p><strong>职责</strong>：</p><ul><li>热点数据缓存</li><li>排行榜实时计算</li><li>会话状态存储</li><li>分布式锁</li></ul><h3 id="_8-其他服务" tabindex="-1"><a class="header-anchor" href="#_8-其他服务"><span>8. 其他服务</span></a></h3><h4 id="chatapp-聊天服务" tabindex="-1"><a class="header-anchor" href="#chatapp-聊天服务"><span>ChatApp（聊天服务）</span></a></h4><p><strong>职责</strong>：</p><ul><li>频道聊天（世界、公会、队伍）</li><li>私聊</li><li>系统广播</li><li>敏感词过滤</li></ul><h4 id="matchapp-匹配服务" tabindex="-1"><a class="header-anchor" href="#matchapp-匹配服务"><span>MatchApp（匹配服务）</span></a></h4><p><strong>职责</strong>：</p><ul><li>玩家匹配（PVP、副本）</li><li>队伍组建</li><li>匹配算法（ELO、段位）</li></ul><hr><h2 id="通信方式总结" tabindex="-1"><a class="header-anchor" href="#通信方式总结"><span>通信方式总结</span></a></h2><h3 id="通信协议栈" tabindex="-1"><a class="header-anchor" href="#通信协议栈"><span>通信协议栈</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────────┐</span>
<span class="line">│                      业务协议层                              │</span>
<span class="line">│   Protobuf消息定义 + RPC接口定义                            │</span>
<span class="line">└─────────────────────────────────────────────────────────────┘</span>
<span class="line">                            ↓</span>
<span class="line">┌─────────────────────────────────────────────────────────────┐</span>
<span class="line">│                      传输协议层                              │</span>
<span class="line">│   客户端↔网关: TCP/KCP/WebSocket                            │</span>
<span class="line">│   内部服务: TCP长连接                                        │</span>
<span class="line">└─────────────────────────────────────────────────────────────┘</span>
<span class="line">                            ↓</span>
<span class="line">┌─────────────────────────────────────────────────────────────┐</span>
<span class="line">│                      网络层                                  │</span>
<span class="line">│   IP + 路由                                                 │</span>
<span class="line">└─────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="消息格式" tabindex="-1"><a class="header-anchor" href="#消息格式"><span>消息格式</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌──────────────┬──────────────┬──────────────┬──────────────┐</span>
<span class="line">│   PacketLen  │   MsgType    │   MsgID      │   Body       │</span>
<span class="line">│   (4 bytes)  │   (2 bytes)  │   (4 bytes)  │   (Protobuf) │</span>
<span class="line">└──────────────┴──────────────┴──────────────┴──────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="rpc调用流程" tabindex="-1"><a class="header-anchor" href="#rpc调用流程"><span>RPC调用流程</span></a></h3>`,58),a(f,{code:`eJwrTi0sTc1LTnXJTEwvSszlUgCCgsSikszkzILEvBIFR4XEYoVnc3qfdi10xJB0Qkg6cYFlHXXt7JysFIICnF+s3/5sY5NGEMj84hJPFx0F39SSjPwUHYWARKBFxZpg9U66QA2OYA1PJ/c+3TUFWUNQanFpTom+a1FRfpEmxHy//JJUhfyy1CIFRx2gPU/3ND1bu/TpkpbnE9re7+l5NmX9s57Gpzu3Pe2fCLGfCwDpJFlt`}),s[3]||=e(`<hr><h2 id="架构特点总结" tabindex="-1"><a class="header-anchor" href="#架构特点总结"><span>架构特点总结</span></a></h2><table><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td><strong>分层设计</strong></td><td>客户端→网关→业务服务→数据服务，职责清晰</td></tr><tr><td><strong>空间分离</strong></td><td>BaseApp处理非空间逻辑，CellApp处理空间逻辑</td></tr><tr><td><strong>水平扩展</strong></td><td>BaseApp/CellApp可动态增减</td></tr><tr><td><strong>高可用</strong></td><td>无单点故障，各服务可多实例部署</td></tr><tr><td><strong>异步通信</strong></td><td>内部采用异步RPC，提高吞吐量</td></tr></tbody></table><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://imgamer.gitbooks.io/kbengine-overview/content/content/5_2DesignIntroduction.html" target="_blank" rel="noopener noreferrer">KBEngine 技术概览 - 软件组件</a></li><li><a href="https://blog.csdn.net/monokai/article/details/151142091" target="_blank" rel="noopener noreferrer">BigWorld Cell 架构设计介绍</a></li></ul>`,6)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};